import { useState } from "react";
import logo from "./assets/logo.png";

const PAYMENT_LINK = "https://your-payment-link.com"; // 🔥 PUT YOUR REAL LINK HERE

function App() {
  const [text, setText] = useState("");
  const [cvText, setCvText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleExtract = async () => {
    if (!text) return;

    setLoading(true);

    try {
      const response = await fetch("http://127.0.0.1:8000/extract", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          job_description: text,
          cv: cvText,
        }),
      });

      const data = await response.json();
      setResult(data);
    } catch (err) {
      console.error(err);
    }

    setLoading(false);
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://127.0.0.1:8000/upload-cv", {
      method: "POST",
      body: formData,
    });

    const data = await res.json();
    setCvText(data.text);
  };

  const hasCV = cvText.trim().length > 0;
  const score = result?.score;

  return (
    <div className="min-h-screen bg-slate-950 text-white">

      {/* NAVBAR */}
      <div className="flex justify-between items-center px-10 py-4 border-b border-slate-800 bg-slate-950/70 backdrop-blur">
        {/* LEFT */}
        <div className="flex items-center gap-3">
          {/* LOGO */}
          <div className="relative">
            <div className="w-8 h-8 rounded-md bg-gradient-to-br from-indigo-500 to-purple-600"></div>
            <div className="absolute inset-0 flex items-center justify-center text-xs font-bold">
              J
            </div>
          </div>

          {/* NAME */}
          <span className="text-lg font-semibold tracking-tight">JobMatch</span>

          <span className="text-xs text-gray-500 hidden sm:block">
            AI-powered insights
          </span>
        </div>

        {/* RIGHT */}
        <button
          onClick={() => window.open(PAYMENT_LINK, "_blank")}
          className="bg-green-500 hover:bg-green-600 transition px-5 py-2 rounded-lg text-sm font-medium shadow"
        >
          Upgrade — $3
        </button>
      </div>

      {/* MAIN */}
      <div className="max-w-6xl mx-auto p-8 grid md:grid-cols-2 gap-8">
        {/* INPUT */}
        <div className="bg-slate-900 p-6 rounded-xl border border-slate-800 space-y-4">
          <textarea
            className="w-full h-40 p-4 rounded-lg bg-slate-950 border border-slate-700"
            placeholder="Paste job description..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />

          <textarea
            className="w-full h-28 p-4 rounded-lg bg-slate-950 border border-slate-700"
            placeholder="Paste your CV (or upload below)"
            value={cvText}
            onChange={(e) => setCvText(e.target.value)}
          />

          <input type="file" onChange={handleFileUpload} />

          <button
            onClick={handleExtract}
            className="w-full py-3 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-lg font-semibold"
          >
            {loading ? "Analyzing..." : "Analyze Job Match"}
          </button>
        </div>

        {/* RESULTS */}
        <div className="bg-slate-900 p-6 rounded-xl border border-slate-800 space-y-6">
          {!result && (
            <p className="text-gray-500 text-center">
              Paste a job description to start
            </p>
          )}

          {result && (
            <>
              {/* SCORE */}
              <div className="bg-slate-950 p-4 rounded-lg">
                <p className="text-sm text-gray-400">Match Score</p>

                {!hasCV ? (
                  <p className="text-gray-500 mt-2">
                    Upload your CV to unlock your match score
                  </p>
                ) : (
                  <>
                    <p className="text-3xl font-bold text-indigo-400">
                      {score}%
                    </p>
                    <p className="text-sm text-gray-400 mt-1">
                      {result.explanation}
                    </p>
                  </>
                )}
              </div>

              {/* CORE SKILLS */}
              <Section title="Core Skills" items={result.core_skills} />

              {/* ALL SKILLS */}
              <Section title="All Skills" items={result.skills} />

              {/* MISSING PREVIEW */}
              <div>
                <h3 className="mb-2">Missing Skills</h3>
                <Section items={result.missing_skills?.slice(0, 2)} />
              </div>

              {/* PAYWALL */}
              <Paywall />

              {/* LEVEL */}
              <div className="bg-slate-950 p-4 rounded-lg">
                <p className="text-sm text-gray-400">Level</p>
                <p className="text-indigo-400">{result.level}</p>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function Section({ title, items = [] }) {
  return (
    <div>
      {title && <h3 className="mb-2">{title}</h3>}
      <div className="flex flex-wrap gap-2">
        {(items || []).map((item, i) => (
          <span key={i} className="bg-slate-700 px-3 py-1 rounded text-sm">
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}

function Paywall() {
  return (
    <div className="bg-slate-950 p-6 rounded-xl text-center border border-slate-800">
      <p className="text-lg font-semibold mb-2">
        🔒 Unlock Your Full Report — $3
      </p>

      <p className="text-sm text-gray-400 mb-4">
        See exactly why you’re not getting hired and how to fix it
      </p>

      <ul className="text-sm text-gray-300 mb-4 space-y-1">
        <li>• Why you’ll get rejected</li>
        <li>• Top priority skills</li>
        <li>• Full missing skills</li>
        <li>• Step-by-step roadmap</li>
      </ul>

      <button
        onClick={() => window.open(PAYMENT_LINK, "_blank")}
        className="bg-green-500 px-6 py-2 rounded-lg font-semibold"
      >
        Get Full Report — $3
      </button>
    </div>
  );
}

export default App;
